'use strict';
let plannedScenes=[],scenePlannerProject=null;
const sceneObjectKeywords={laptop:/\b(computer|laptop|software|website|coding|online|digital)\b/gi,phone:/\b(phone|mobile|call|app|smartphone)\b/gi,coins:/\b(money|cost|price|budget|profit|saving|savings|income)\b/gi,chart:/\b(growth|data|chart|statistics|sales|increase|results)\b/gi,books:/\b(book|books|study|education|learn|learning|school|knowledge)\b/gi,lightbulb:/\b(idea|ideas|solution|discover|innovation|creative)\b/gi,gear:/\b(process|system|engine|workflow|automation|machine)\b/gi,clock:/\b(time|deadline|minute|hour|schedule|faster)\b/gi,calendar:/\b(date|calendar|meeting|appointment|week|month)\b/gi,folder:/\b(project|document|file|files|organize|plan)\b/gi,megaphone:/\b(announce|marketing|advertise|campaign|audience|promote)\b/gi,bubble:/\b(message|talk|conversation|communicate|discuss|chat)\b/gi,globe:/\b(world|global|country|countries|international|planet)\b/gi,plant:/\b(plant|nature|environment|green|sustainable|sustainability)\b/gi,coffee:/\b(coffee|break|morning|cafe)\b/gi,briefcase:/\b(business|career|job|work|office|professional)\b/gi};
function suggestSceneObjects(text){return Object.entries(sceneObjectKeywords).map(([id,re])=>({id,score:(text.match(re)||[]).length})).filter(a=>a.score).sort((a,b)=>b.score-a.score).slice(0,3).map(a=>a.id)}
function plannerActorTemplates(){const map=new Map();for(const s of project.scenes)for(const o of storyActors(s))if(!map.has(o.name.toLowerCase()))map.set(o.name.toLowerCase(),o);return[...map.values()]}
function parseStoryboardScript(text,presenter=null){if(typeof text!=='string'||!text.trim())throw Error('Paste or write a script first.');if(text.length>40000)throw Error('Plan up to 40,000 characters at a time.');const blocks=[];let title='',lines=[];const flush=()=>{if(lines.length){blocks.push({title,lines});lines=[];title=''}};for(const raw of text.split(/\r?\n/)){const line=raw.trim(),heading=line.match(/^(?:#{1,3}\s+|scene\s+\d+\s*[:.—-]?\s*|scene\s*:\s*)(.*)$/i);if(heading){flush();title=heading[1].trim();continue}if(!line){flush();continue}lines.push(line)}flush();const plans=[];for(const block of blocks){let chunk=[],count=0,number=0;const push=()=>{if(!chunk.length)return;const combined=chunk.map(l=>l.text).join(' '),words=combined.trim().split(/\s+/).length,objects=suggestSceneObjects(combined);plans.push({id:uid(),title:(block.title||combined.split(/[.!?]/)[0].split(/\s+/).slice(0,7).join(' ')).slice(0,80)+(number?' · continued':''),lines:chunk,text:combined,duration:clamp(Math.ceil(words/2.5+chunk.length*.3+1),3,60),objects:objects.slice(0,1),suggestedObjects:objects,presenter,shot:'wide'});chunk=[];count=0;number++};for(const input of block.lines){const match=input.match(/^([^:]{1,80}):\s*(.*)$/),speaker=match?match[1].trim():null,words=(match?match[2]:input).split(/\s+/).filter(Boolean);while(words.length){const room=100-count;if(!room){push();continue}const take=words.splice(0,room);chunk.push({speaker,text:take.join(' ')});count+=take.length;if(count>=100)push()}}push()}if(plans.length>30)throw Error('This script needs more than 30 scenes. Plan it in smaller sections.');return plans}
document.querySelector('.studio-toolbar').insertAdjacentHTML('beforeend','<button id="openScenePlanner">Plan scenes from script</button>');$('storyToolsDialog').querySelector('.story-topbar').append(storyButton('Plan scenes',()=>{$('storyToolsDialog').close();openScenePlanner()}));
document.body.insertAdjacentHTML('beforeend',`<dialog id="scenePlannerDialog"><div class="tool-heading"><div><div class="eyebrow">SCRIPT TO STORYBOARD</div><h2>Plan your scenes</h2></div><button id="closeScenePlanner">Close</button></div><textarea id="scenePlannerScript" rows="6" maxlength="40000" placeholder="Write paragraphs or use SCENE 1: Title. Dialogue can use Character: words." aria-label="Storyboard script"></textarea><div class="planner-toolbar"><label>Presenter<select id="scenePlannerPresenter"></select></label><button id="analyzeSceneScript" class="primary">Suggest scenes</button><button id="createPlannedScenes" disabled>Add planned scenes</button></div><p id="scenePlannerStatus" role="status" class="note">Local suggestions use script structure and keywords. Review titles, timing, objects and framing before adding scenes. Voice generation is available afterward in Script.</p><div id="scenePlannerCards"></div></dialog>`);
function openScenePlanner(){stop();const e=$('scenePlannerPresenter');e.innerHTML='<option value="">No default presenter</option>';for(const actor of plannerActorTemplates()){const option=document.createElement('option');option.value=actor.id;option.textContent=actor.name;e.append(option)}for(const cast of project.cast){const option=document.createElement('option');option.value='cast:'+cast.id;option.textContent=cast.name+' · cast';e.append(option)}e.value=isAnimatedCharacter(object())?object().id:plannerActorTemplates()[0]?.id||('cast:'+project.cast[0]?.id);if(!plannedScenes.length)$('scenePlannerScript').value=storyLines(current()).map(l=>actorName(current(),l.speakerId)+': '+l.text).join('\n');scenePlannerProject=project;$('scenePlannerDialog').showModal();renderPlannedScenes()}
function renderPlannedScenes(){const list=$('scenePlannerCards');list.replaceChildren();$('createPlannedScenes').disabled=!plannedScenes.length;$('createPlannedScenes').textContent='Add '+plannedScenes.length+' planned scenes';for(const [index,plan]of plannedScenes.entries()){const card=document.createElement('section');card.className='scene-plan-card';const head=document.createElement('div');head.className='planner-toolbar';const title=document.createElement('input');title.value=plan.title;title.maxLength=80;title.setAttribute('aria-label','Scene '+(index+1)+' title');title.onchange=()=>plan.title=title.value;const length=storyNumber(plan.duration,1,60,n=>plan.duration=n,'Scene '+(index+1)+' duration');const shot=storySelect(Object.entries(storyShotTypes).filter(([id])=>['wide','medium','close'].includes(id)),plan.shot,id=>plan.shot=id,'Scene '+(index+1)+' framing');head.append(title,storyLabel('Seconds',length),shot,storyButton('Remove',()=>{plannedScenes=plannedScenes.filter(p=>p!==plan);renderPlannedScenes()}));const text=document.createElement('p');text.className='note';text.textContent=plan.lines.map(line=>(line.speaker?line.speaker+': ':'')+line.text).join('\n');const assets=document.createElement('div');assets.className='planner-objects';for(const id of new Set([...plan.suggestedObjects,...plan.objects])){const item=explainerObjects.find(o=>o.id===id),label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=plan.objects.includes(id);check.onchange=()=>{if(check.checked&&!plan.objects.includes(id)){if(plan.objects.length>=3){check.checked=false;return toast('Use up to three suggested objects per scene.')}plan.objects.push(id)}else if(!check.checked)plan.objects=plan.objects.filter(a=>a!==id)};label.append(check,document.createTextNode(item.name));assets.append(label)}const extra=storySelect([['','Add another object…'],...explainerObjects.map(i=>[i.id,i.name])],'',id=>{if(id&&!plan.objects.includes(id)){if(plan.objects.length>=3)return toast('Use up to three objects per scene.');plan.objects.push(id);renderPlannedScenes()}},'Scene '+(index+1)+' object');assets.append(extra);card.append(head,text,assets);list.append(card)}}
async function createStoryboardScenes(plans=plannedScenes){plans=structuredClone(plans);if(!plans.length)throw Error('Suggest scenes first.');if(project!==scenePlannerProject)throw Error('The project changed. Reopen the scene planner.');if(project.scenes.length+plans.length>=100)throw Error('Keep fewer than 100 scenes.');const captured=project,templates=plannerActorTemplates(),built=[];for(const plan of plans){const s=scene(plan.title||'Planned scene','#fbf3e2','blank');s.duration=clamp(plan.duration,1,60);const view=projectView(),actorMap=new Map(),actorCopies=[];function getActor(token){let original=templates.find(o=>o.id===token||o.name.toLowerCase()===String(token).toLowerCase()),cast=String(token).startsWith('cast:')?project.cast.find(c=>c.id===token.slice(5)):null;if(!original&&!cast)return null;const key=original?.id||cast.id;if(actorMap.has(key))return actorMap.get(key);const o=original?continuitySnapshot(original,project.scenes.find(s=>s.objects.includes(original)),0):templateObject('character',{character:structuredClone(cast),name:cast.name,autoBlink:true},280,440);o.id=uid();delete o.continuityId;delete o.continuitySource;o.name=original?.name||cast.name;actorCopies.push(o);actorMap.set(key,o);return o}const presenter=plan.presenter?getActor(plan.presenter):null;s.dialogue=plan.lines.map(l=>{const speaker=l.speaker&&l.speaker.toLowerCase()!=='narrator'?getActor(l.speaker):presenter&&l.speaker===null?presenter:null;return makeStoryLine(l.text,speaker?.id||null)});const desired=s.dialogue.reduce((n,l)=>n+l.duration,0),gap=Math.min(.3,s.duration/(s.dialogue.length*4)),available=Math.max(.1*s.dialogue.length,s.duration-gap*Math.max(0,s.dialogue.length-1));let at=0;for(const l of s.dialogue){l.duration=Math.max(.1,l.duration/Math.max(.1,desired)*available);l.start=at;l.pause=gap;at+=l.duration+gap}s.dialogueArranged=false;actorCopies.forEach((o,i)=>{o.keys=[{t:0,v:{...pose,...rigDefaults,...o.keys[0].v,x:view.left+view.width*(actorCopies.length>1?.2+(i%3)*.28:.28),y:450,scale:actorCopies.length>1?.7:.9}}];o.in=0;o.out=s.duration;s.objects.push(o)});for(const [i,id]of plan.objects.entries()){const meta={...explainerOptions,id,style:'vector',motion:'pop',details:true},src=await explainerSource(id,'vector',meta);await imageReady(src);const name=explainerObjects.find(a=>a.id===id)?.name||id;const o=templateObject('image',{name,src,explainerAsset:meta},view.left+view.width*(plan.objects.length>1?.48+i*.17:.72),280,view.width<400?.8:1.25);s.objects.push(o)}const font=view.width<400?(s.name.length>45?18:23):34,maxChars=Math.max(12,Math.floor((view.width-30)/(font*.58)));const words=s.name.split(/\s+/),titleLines=[];let titleLine='';for(const word of words){if(titleLine.length+word.length+1>maxChars&&titleLine){titleLines.push(titleLine);titleLine=''}titleLine+=(titleLine?' ':'')+word}if(titleLine)titleLines.push(titleLine);const title=templateText(titleLines.join('\n'),480,55,font,'#344259');title.textEffect='fade';title.textDuration=.6;s.objects.push(title);s.scenePlan={method:'local-script-keywords',text:plan.text.slice(0,4000)};s._plannedShot=plan.shot;built.push(s)}if(project!==captured)throw Error('The project changed while preparing scenes.');const candidate={...project,scenes:[...project.scenes,...built]};if(!valid(candidate))throw Error('This plan contains invalid timing. Adjust the scene lengths.');const first=project.scenes.length;project.scenes.push(...built);for(const s of built){const actor=storyActors(s)[0];const wide=storeStoryShot({type:'wide',actorId:null,otherId:null,at:0,ease:0,follow:false},s),boxes=s.objects.map(o=>storyActorBox(o,Math.min(.8,s.duration*.8))),box=unionStoryBoxes(boxes),view=projectView();wide.camera={x:box.x+box.w/2,y:box.y+box.h/2,zoom:clamp(Math.min(view.width/(box.w*1.12),view.height/(box.h*1.12)),.25,6)};if(actor&&s._plannedShot!=='wide')storeStoryShot({type:s._plannedShot,actorId:actor.id,otherId:null,at:Math.min(.45,s.duration*.2),ease:.25,follow:true},s);delete s._plannedShot}sceneIndex=first;time=0;selectLayers([]);save();render();return built}
$('openScenePlanner').onclick=openScenePlanner;$('closeScenePlanner').onclick=()=>{if(!creatingPlannedScenes)$('scenePlannerDialog').close()};$('analyzeSceneScript').onclick=()=>{try{scenePlannerProject=project;plannedScenes=parseStoryboardScript($('scenePlannerScript').value,$('scenePlannerPresenter').value||null);renderPlannedScenes();$('scenePlannerStatus').textContent=plannedScenes.length+' suggested scenes. Review and adjust before adding them.'}catch(e){$('scenePlannerStatus').textContent=e.message}};let creatingPlannedScenes=false;$('createPlannedScenes').onclick=async()=>{if(creatingPlannedScenes)return;creatingPlannedScenes=true;window.editorTaskBusy=true;const frozen=[...$('scenePlannerDialog').querySelectorAll('button,input,textarea,select')].map(e=>[e,e.disabled]);frozen.forEach(([e])=>e.disabled=true);try{const scenes=await createStoryboardScenes();plannedScenes=[];$('scenePlannerDialog').close();toast(scenes.length+' editable storyboard scenes added. Create voices in Script.')}catch(e){$('scenePlannerStatus').textContent=e.message}finally{creatingPlannedScenes=false;window.editorTaskBusy=false;frozen.forEach(([e,disabled])=>e.disabled=disabled);$('createPlannedScenes').disabled=!plannedScenes.length}};$('scenePlannerDialog').addEventListener('cancel',e=>{if(creatingPlannedScenes)e.preventDefault()});
